// Vehicle placements: the part at each site of a vehicle, where it sits in the vehicle frame and whether it is a
// mirrored far-side twin. Sources are models/vehicles/<vehicle>.placements.libsonnet, built from
// models/vehicles/site.libsonnet; the why is in docs/decisions/0001-vehicle-placements.md.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { compileJsonnetFile } from './jsonnet/index.mjs';
import { outputPath } from './layout.mjs';

const repo = resolve(import.meta.dirname, '..');
// Generated by tools/vehicle-index.mjs: every vehicle's sites under its name.
export const PLACEMENTS_SOURCE = 'models/vehicles/placements.libsonnet';
const SITE_KEYS = new Set(['id', 'part', 'at', 'mirror']);

export const placementsPath = (vehicle) => `vehicles/${vehicle}.placements.json`;

// vehicle -> its sites, compiled from the sources.
export const readPlacements = (root = repo) => JSON.parse(compileJsonnetFile(PLACEMENTS_SOURCE, root));

const isPoint = (at) => Array.isArray(at) && at.length === 3 && at.every(Number.isFinite);

// Why each vehicle's sites could not be assembled from the built models, as messages. placements: vehicle -> sites;
// models: the built models, { id, pack }. A part is named by its model id alone, so the id must name one model.
export function placementProblems(placements, models) {
  const packsOf = new Map();
  for (const { id, pack } of models) packsOf.set(id, [...(packsOf.get(id) ?? []), pack]);
  const problems = [];
  for (const [vehicle, sites] of Object.entries(placements)) {
    if (!Array.isArray(sites) || sites.length === 0) {
      problems.push(`${vehicle}: no sites`);
      continue;
    }
    const seen = new Set();
    for (const site of sites) {
      const where = `${vehicle}/${site?.id}`;
      const unknown = Object.keys(site ?? {}).filter((key) => !SITE_KEYS.has(key));
      if (unknown.length > 0) problems.push(`${where}: unknown keys ${unknown.join(' ')}`);
      if (typeof site?.id !== 'string' || site.id === '') problems.push(`${vehicle}: a site without an id`);
      else if (seen.has(site.id)) problems.push(`${where}: two sites of one id`);
      else seen.add(site.id);
      if (!isPoint(site?.at)) problems.push(`${where}: at is not three finite numbers`);
      if (site?.mirror !== undefined && site.mirror !== true) problems.push(`${where}: mirror is true or absent`);
      const packs = packsOf.get(site?.part) ?? [];
      if (packs.length === 0) problems.push(`${where}: ${site?.part} is not a built model`);
      if (packs.length > 1) problems.push(`${where}: ${site.part} is built in ${packs.length} packs, ${packs.join(' ')}`);
    }
  }
  return problems.sort();
}

// Writes each vehicle's sites under the pack of its root part, its first site, which is the body every other part is
// placed on. Returns the vehicles written, { id, pack, path }, and every file as <pack>/<logical path>.
export function exportPlacements({ placements, models, out }) {
  const problems = placementProblems(placements, models);
  if (problems.length > 0) throw new Error(`vehicle placements:\n  ${problems.join('\n  ')}`);
  const packOf = new Map(models.map(({ id, pack }) => [id, pack]));
  const vehicles = Object.entries(placements).sort(([a], [b]) => (a < b ? -1 : 1)).map(([vehicle, sites]) => {
    const pack = packOf.get(sites[0].part);
    const path = placementsPath(vehicle);
    const file = join(out, outputPath(pack, path));
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, `${JSON.stringify({ sites }, null, 2)}\n`);
    return { id: vehicle, pack, path };
  });
  return { vehicles, files: vehicles.map(({ pack, path }) => outputPath(pack, path)) };
}
